#!/usr/bin/env python
#
# This script generates the README files for the repository and for each image. The READMEs for the images are synced
# to the image's repository on Docker Hub and AWS ECR Public Gallery by the `sync-readmes` workflow.
#
# Language versions are read from `.github/scripts/matrix/versions.py` and the Dockerfiles, so that the READMEs can't
# drift from what we actually ship. Do not edit the generated files by hand, edit this script instead and run:
#
#     python ./.github/scripts/readme/gen-readmes.py
#
# Pass `--check` to fail if any generated file is out of date instead of writing it. This is used in CI.
#
import os
import re
import sys

sys.dont_write_bytecode = True

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "matrix"))
import versions  # noqa: E402

import images  # noqa: E402

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", ".."))
CHECK = len(sys.argv) > 1 and sys.argv[1] == "--check"

REPO_URL = "https://github.com/pulumi/pulumi-docker-containers"
HUB_URL = "https://hub.docker.com/r/pulumi"
ECR_URL = "https://gallery.ecr.aws/pulumi"
GHCR_URL = "https://github.com/orgs/pulumi/packages/container/package"

# Docker Hub rejects descriptions larger than 25,000 bytes.
MAX_README_BYTES = 25000

GENERATED_HEADER = (
    "<!-- This file is generated by .github/scripts/readme/gen-readmes.py. Do not edit it by hand. -->\n\n"
)


def read(path):
    with open(os.path.join(ROOT, path)) as f:
        return f.read()


def find_all(pattern, text, path):
    matches = re.findall(pattern, text, re.MULTILINE)
    if not matches:
        sys.exit(f"error: no match for {pattern!r} in {path}, update gen-readmes.py to match the Dockerfile")
    return matches


def find_one(pattern, text, path):
    return find_all(pattern, text, path)[0]


def version_key(version):
    return tuple(int(part) for part in version.split("."))


def sorted_versions(values):
    return sorted(set(values), key=version_key)


def kitchen_sink_versions():
    path = "docker/pulumi/Dockerfile"
    dockerfile = read(path)
    return {
        "go": find_one(r"^ENV GOLANG_VERSION (\S+)", dockerfile, path),
        "java": find_one(r"openjdk-(\d+)-jdk", dockerfile, path),
        "dotnet": sorted_versions(find_all(r"dotnet-install\.sh \| bash -s -- --channel (\S+)", dockerfile, path)),
        "python": sorted_versions(find_all(r"^RUN pyenv install (\S+)", dockerfile, path)),
        "python_default": find_one(r"^RUN pyenv global (\S+)", dockerfile, path),
        "nodejs": sorted_versions(find_all(r"fnm install (\d+)", dockerfile, path)),
        "nodejs_default": find_one(r"fnm alias (\d+) default", dockerfile, path),
    }


def slim_versions():
    go_path = "docker/go/Dockerfile.debian"
    java_path = "docker/java/Dockerfile.debian"
    return {
        "go": find_one(r"^ARG GO_RUNTIME_VERSION=(\S+)", read(go_path), go_path),
        "java": find_one(r"openjdk-(\d+)-jdk", read(java_path), java_path),
    }


KS = kitchen_sink_versions()
SLIM = slim_versions()


def hub(repo):
    return f"{HUB_URL}/{repo}"


def ecr(repo):
    return f"{ECR_URL}/{repo}"


def ghcr(repo):
    return f"{GHCR_URL}/{repo}"


def join(values):
    values = list(values)
    if len(values) == 1:
        return values[0]
    if len(values) == 2:
        return f"{values[0]} and {values[1]}"
    return ", ".join(values[:-1]) + f", and {values[-1]}"


INTRO = """\
**Pulumi IaC: infrastructure as code in any programming language.**

[Pulumi IaC](https://www.pulumi.com/product/infrastructure-as-code/) is an open-source infrastructure as code tool \
for creating, deploying, and managing cloud infrastructure on any cloud. Write your infrastructure in \
TypeScript, JavaScript, Python, Go, C#, Java, or YAML, and use the loops, functions, classes, testing tools, and \
package managers you already know.
"""

ISSUES = f"""\
## Getting help

- Problems with an image, such as a missing tool, a vulnerability, or a broken tag: \
[open an issue in pulumi/pulumi-docker-containers]({REPO_URL}/issues/new).
- Problems with the Pulumi CLI or SDKs: [open an issue in pulumi/pulumi](https://github.com/pulumi/pulumi/issues/new/choose).
- Questions: ask in the [Pulumi Community Slack](https://slack.pulumi.com/).
"""

RELEASES = """\
## Releases

Images are built and published automatically for every release of the \
[Pulumi CLI](https://github.com/pulumi/pulumi/releases), usually once a week, with patch releases in between when \
needed. Image tags match the version of the Pulumi CLI they contain. For example, when Pulumi `v3.200.0` is \
released, it's published as `3.200.0`. The `latest` tag always points to the most recent release.

To avoid unexpected upgrades, pin your image to a specific version tag rather than `latest`.

Images are scanned nightly for vulnerabilities. We remediate findings where we can, on a best-effort basis. Some \
findings, such as vulnerabilities in base images with no available fix, are outside our control.
"""


def registries(repos):
    rows = "\n".join(f"| `pulumi/{r}` | [Docker Hub]({hub(r)}) | [ECR Public]({ecr(r)}) | [GHCR]({ghcr(r)}) |" for r in repos)
    return f"""\
## Registries

Every image is published to Docker Hub, the AWS ECR Public Gallery, and the GitHub Container Registry.

| Image | Docker Hub | ECR Public | GHCR |
| --- | --- | --- | --- |
{rows}

For example, `docker pull pulumi/{repos[0]}`, `docker pull public.ecr.aws/pulumi/{repos[0]}`, or \
`docker pull ghcr.io/pulumi/{repos[0]}`.
"""


def footer(repos):
    return "\n".join([
        registries(repos),
        RELEASES,
        ISSUES,
        f"## Source\n\nThe Dockerfiles for this image are in [pulumi/pulumi-docker-containers]({REPO_URL}).\n",
    ])


SLIM_TAGS = f"""\
## Tags and platforms

Each Pulumi release is published under these tags, where `<version>` is the Pulumi CLI version, for example `3.200.0`:

| Tag | Base image | Platforms |
| --- | --- | --- |
| `<version>`, `latest` | Debian 13 (trixie) slim | `linux/amd64`, `linux/arm64` |
| `<version>-debian` | Debian 13 (trixie) slim | `linux/amd64`, `linux/arm64` |
| `<version>-debian-amd64` | Debian 13 (trixie) slim | `linux/amd64` |
| `<version>-debian-arm64` | Debian 13 (trixie) slim | `linux/arm64` |
| `<version>-ubi` | [Red Hat UBI 9 minimal](https://hub.docker.com/r/redhat/ubi9-minimal) | `linux/amd64` |

Tags without a suffix are the same image as the `-debian` tag. The `-debian` tag is a multi-platform manifest list, \
so `docker pull` selects the right image for your machine. UBI images use \
[`microdnf`](https://github.com/rpm-software-management/microdnf) as their package manager.
"""

BASE_TAGS = SLIM_TAGS.replace(
    "| `<version>-ubi` | [Red Hat UBI 9 minimal](https://hub.docker.com/r/redhat/ubi9-minimal) | `linux/amd64` |",
    "| `<version>-ubi` | [Red Hat UBI 9 minimal](https://hub.docker.com/r/redhat/ubi9-minimal) | `linux/amd64`, `linux/arm64` |\n"
    "| `<version>-ubi-amd64` | Red Hat UBI 9 minimal | `linux/amd64` |\n"
    "| `<version>-ubi-arm64` | Red Hat UBI 9 minimal | `linux/arm64` |",
)


def slim_usage(repo):
    return f"""\
## Usage

Mount your Pulumi project into the container and run Pulumi commands against it:

```bash
docker run --rm -it \\
  -e PULUMI_ACCESS_TOKEN \\
  -v "$(pwd)":/pulumi/projects \\
  -w /pulumi/projects \\
  pulumi/{repo} \\
  pulumi preview
```

Pass the credentials for your cloud provider as environment variables, too. This image contains only the Pulumi CLI \
and the tools listed above. If your program needs other tools, such as `helm` for the Kubernetes provider, use this \
image as the base for your own image and install them there. The [`pulumi/pulumi`]({hub("pulumi")}) image includes \
many common tools.
"""


def versioned_section(sdk, label):
    info = versions.versioned[sdk]
    all_versions = sorted_versions([info["default"]] + info["additional"])
    rows = "\n".join(
        f"| `pulumi/pulumi-{sdk}-{v}` | {label} {v}{' (default)' if v == info['default'] else ''} |"
        for v in all_versions
    )
    return f"""\
## {label} versions

`pulumi/pulumi-{sdk}` ships {label} {info["default"]}. To use a different version of {label}, use the image for that \
version instead:

| Image | {label} version |
| --- | --- |
| `pulumi/pulumi-{sdk}` | {label} {info["default"]} |
{rows}

The versions on offer follow the supported releases of {label}. When the default changes, `pulumi/pulumi-{sdk}` moves \
to the new version, so pin an image with a version in its name if you need to stay on a specific one.
"""


def versioned_repos(sdk):
    info = versions.versioned[sdk]
    return [f"pulumi-{sdk}"] + [f"pulumi-{sdk}-{v}" for v in sorted_versions([info["default"]] + info["additional"])]


def sdk_readme(sdk):
    image = images.IMAGES[f"pulumi-{sdk}"]
    contents = image["contents"](SLIM)
    if sdk in versions.versioned:
        repos = versioned_repos(sdk)
        versions_md = versioned_section(sdk, image["language"])
    else:
        repos = [f"pulumi-{sdk}"]
        versions_md = ""
    parts = [
        f"# pulumi/pulumi-{sdk}\n",
        INTRO,
        f"## About this image\n\n{image['about']}\n\nIt contains:\n\n{contents}\n",
        versions_md,
        SLIM_TAGS,
        slim_usage(f"pulumi-{sdk}"),
        footer(repos),
    ]
    return "\n".join(p for p in parts if p)


def base_readme():
    return "\n".join([
        "# pulumi/pulumi-base\n",
        INTRO,
        f"""\
## About this image

A slim image that contains the Pulumi CLI and its language plugins, but no language toolchains such as Node.js or \
Python. Use it as a base for your own image when you want to choose exactly which languages and tools to install. For an image with a language already \
installed, see [`pulumi/pulumi-nodejs`]({hub("pulumi-nodejs")}), [`pulumi/pulumi-python`]({hub("pulumi-python")}), \
[`pulumi/pulumi-go`]({hub("pulumi-go")}), [`pulumi/pulumi-dotnet`]({hub("pulumi-dotnet")}), or \
[`pulumi/pulumi-java`]({hub("pulumi-java")}).
""",
        BASE_TAGS,
        slim_usage("pulumi-base"),
        footer(["pulumi-base"]),
    ])


def kitchen_sink_contents():
    return f"""\
- The Pulumi CLI, all Pulumi language runtimes, and the OPA policy analyzer.
- Node.js {join(KS["nodejs"])} (default {KS["nodejs_default"]}), managed by [fnm](https://github.com/Schniz/fnm), \
with npm, Yarn, pnpm, Bun, and Corepack.
- Python {join(KS["python"])} (default {KS["python_default"]}), managed by [pyenv](https://github.com/pyenv/pyenv), \
with pip, Poetry, and uv.
- Go {KS["go"]}.
- .NET SDK {join(KS["dotnet"])}.
- OpenJDK {KS["java"]}.
- Cloud and container tools: the AWS CLI, `aws-iam-authenticator`, the Azure CLI, the Google Cloud CLI with the GKE \
auth plugin, `kubectl`, Helm, and the Docker CLI."""


def kitchen_sink_tags():
    return """\
## Tags and platforms

Each Pulumi release is published under these tags, where `<version>` is the Pulumi CLI version, for example `3.200.0`:

| Tag | Runs as | Platforms |
| --- | --- | --- |
| `<version>`, `latest` | `root` | `linux/amd64`, `linux/arm64` |
| `<version>-amd64` | `root` | `linux/amd64` |
| `<version>-arm64` | `root` | `linux/arm64` |
| `<version>-nonroot`, `latest-nonroot` | `pulumi` (UID 1000) | `linux/amd64`, `linux/arm64` |
| `<version>-nonroot-amd64` | `pulumi` (UID 1000) | `linux/amd64` |
| `<version>-nonroot-arm64` | `pulumi` (UID 1000) | `linux/arm64` |

The image is based on Debian 13 (trixie). Tags without an architecture suffix are multi-platform manifest lists, so \
`docker pull` selects the right image for your machine.
"""


KITCHEN_SINK_LANGUAGES = f"""\
## Choosing a language version

The `pulumi/pulumi` image includes several versions of Node.js, Python, and .NET. By default, it uses Node.js \
{KS["nodejs_default"]} and Python {KS["python_default"]}. How you select another version depends on the language.

### Node.js

The image uses [fnm](https://github.com/Schniz/fnm) to manage Node.js versions, and comes with the latest patch \
releases of Node.js {join(KS["nodejs"])} installed. To select a version, create a `.node-version` file in your \
project directory with the version you want, then run `pulumi install --use-language-version-tools`. This sets up \
the aliases for Node.js, npm, and the other Node.js tools in `/usr/local/share/fnm/aliases/default/bin`.

To avoid downloading Node.js on every run, specify only the major version, for example `{KS["nodejs_default"]}`. This \
ensures that the preinstalled version is used.

If you're building your own image from `pulumi/pulumi`, run `fnm alias <version> default` to change the default \
version of Node.js in your image.

### Python

The image uses [pyenv](https://github.com/pyenv/pyenv) to manage Python versions, and comes with Python \
{join(KS["python"])} installed. To select a version, create a `.python-version` file in your project directory \
with the version you want.

To avoid downloading and building Python on every run, specify only the minor version, for example \
`{KS["python_default"]}`. This ensures that the preinstalled version is used.

### .NET

The image includes the .NET SDK {join(KS["dotnet"])}. The `TargetFramework` property in your project's `.csproj` \
or `.fsproj` file determines which one is used:

```xml
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <TargetFramework>net{KS["dotnet"][0]}</TargetFramework>
    ...
```

### Go

The `go` directive in your project's `go.mod` file determines the version of Go used to build your program. See \
[Go toolchains](https://go.dev/doc/toolchain).

### Java

The image includes a single version of the JDK, OpenJDK {KS["java"]}.
"""


def kitchen_sink_readme():
    return "\n".join([
        "# pulumi/pulumi\n",
        INTRO,
        f"""\
## About this image

The "kitchen sink" image: the Pulumi CLI with every supported language and a set of common cloud tools, ready to \
run any Pulumi program. It's about 2 GB. If you only use one language, the slim images for each language are much \
smaller, at 200 to 300 MB. See [the full list of images]({REPO_URL}#images).

It contains:

{kitchen_sink_contents()}
""",
        kitchen_sink_tags(),
        f"""\
## Usage

The image's entrypoint is `pulumi`, so pass the Pulumi command as arguments:

```bash
docker run --rm -it \\
  -e PULUMI_ACCESS_TOKEN \\
  -v "$(pwd)":/pulumi/projects \\
  -w /pulumi/projects \\
  pulumi/pulumi \\
  preview
```

Pass the credentials for your cloud provider as environment variables, too.
""",
        KITCHEN_SINK_LANGUAGES,
        footer(["pulumi"]),
    ])


def provider_build_environment_readme():
    return "\n".join([
        "# pulumi/pulumi-provider-build-environment\n",
        INTRO,
        f"""\
## About this image

An image for building Pulumi providers, including providers bridged from Terraform. It's the \
[`pulumi/pulumi`]({hub("pulumi")}) image plus the tools used by the Pulumi provider build process: \
[`pulumictl`](https://github.com/pulumi/pulumictl), [golangci-lint](https://golangci-lint.run/), and \
[GoReleaser](https://goreleaser.com/). Its default command is `bash` instead of `pulumi`.

The image is mostly intended for Pulumi's own provider builds, and its contents change to match their needs. See \
[pulumi/pulumi-docker-containers#111]({REPO_URL}/issues/111) for background.

## Tags and platforms

Each Pulumi release is published under these tags, where `<version>` is the Pulumi CLI version, for example `3.200.0`:

| Tag | Platforms |
| --- | --- |
| `<version>`, `latest` | `linux/amd64`, `linux/arm64` |
| `<version>-amd64` | `linux/amd64` |
| `<version>-arm64` | `linux/arm64` |
""",
        footer(["pulumi-provider-build-environment"]),
    ])


def repo_readme():
    def row(name, path, description):
        return f"| [`pulumi/{name}`]({hub(name)}) | {description} | [README]({REPO_URL}/blob/main/{path}) |"

    rows = [
        row("pulumi", "docker/pulumi/README.md",
            "The \"kitchen sink\" image: the Pulumi CLI, every supported language, and common cloud tools. About 2 GB."),
        row("pulumi-base", "docker/base/README.md", "The Pulumi CLI with no language toolchains. Bring your own."),
    ]
    for name, image in images.IMAGES.items():
        if "sdk" not in image:
            continue
        sdk = image["sdk"]
        description = image["summary"]
        if sdk in versions.versioned:
            info = versions.versioned[sdk]
            others = ", ".join(f"`pulumi-{sdk}-{v}`" for v in sorted_versions([info["default"]] + info["additional"]))
            description += f" Defaults to {image['language']} {info['default']}. Also published per version: {others}."
        rows.append(row(name, f"docker/{sdk}/README.md", description))
    rows.append(row("pulumi-provider-build-environment", "docker/provider-build-environment/README.md",
                    "The kitchen sink image plus tools for building Pulumi providers."))
    table = "\n".join(rows)

    return "\n".join([
        "# pulumi-docker-containers\n",
        "The source for Pulumi's official Docker images.\n",
        INTRO,
        f"""\
## Images

| Image | Description | Details |
| --- | --- | --- |
{table}

The slim language images are much smaller than `pulumi/pulumi`, at 200 to 300 MB compared to about 2 GB.

Each image's README lists its tags, platforms, and language versions. The same README is published as the image's \
description on Docker Hub and the AWS ECR Public Gallery.

## Tags and platforms

Image tags match the version of the Pulumi CLI they contain, and `latest` points to the most recent release.

- `pulumi/pulumi` and `pulumi/pulumi-provider-build-environment` are built on Debian 13 (trixie) for `linux/amd64` \
and `linux/arm64`. `pulumi/pulumi` also has `-nonroot` tags that run as a `pulumi` user.
- The other images are built on two base images:
  - Debian 13 (trixie) slim, for `linux/amd64` and `linux/arm64`, tagged `-debian`. Tags without a suffix are the \
same image as the `-debian` tag.
  - [Red Hat UBI 9 minimal](https://hub.docker.com/r/redhat/ubi9-minimal), tagged `-ubi`. `pulumi/pulumi-base` is \
built for `linux/amd64` and `linux/arm64`, and the language images for `linux/amd64` only.

Images are published to [Docker Hub](https://hub.docker.com/u/pulumi), the \
[AWS ECR Public Gallery](https://gallery.ecr.aws/pulumi/), and the \
[GitHub Container Registry](https://github.com/orgs/pulumi/packages?repo_name=pulumi-docker-containers).

## Language versions

Language versions follow the supported releases of each language. Images without a language version in their name \
use the default:

| Language | Default | Other versions |
| --- | --- | --- |
| Node.js | {versions.versioned["nodejs"]["default"]} | {", ".join(sorted_versions(versions.versioned["nodejs"]["additional"]))} |
| Python | {versions.versioned["python"]["default"]} | {", ".join(sorted_versions(versions.versioned["python"]["additional"]))} |
| .NET | {versions.versioned["dotnet"]["default"]} | {", ".join(sorted_versions(versions.versioned["dotnet"]["additional"]))} |
| Go | {SLIM["go"]} | |
| Java (OpenJDK) | {SLIM["java"]} | |

To choose a version in the slim images, use the image with that version in its name, for example \
`pulumi/pulumi-nodejs-{versions.versioned["nodejs"]["additional"][0]}`. To choose a version in `pulumi/pulumi`, see \
[its README]({REPO_URL}/blob/main/docker/pulumi/README.md#choosing-a-language-version).

## Considerations

The base and language images _don't_ include extra tools you might need for a particular provider. For example, if \
you use the [Kubernetes provider](https://github.com/pulumi/pulumi-kubernetes) with [Helm](https://helm.sh/), use \
one of these images as the base for your own image and install `helm` there, or use `pulumi/pulumi`.
""",
        RELEASES,
        ISSUES,
        f"""\
## Contributing

See [CONTRIBUTING.md]({REPO_URL}/blob/main/CONTRIBUTING.md). The READMEs in this repository are generated by \
`.github/scripts/readme/gen-readmes.py`, so edit that script instead of the READMEs.
""",
    ])


def outputs():
    yield "README.md", repo_readme()
    yield "docker/pulumi/README.md", kitchen_sink_readme()
    yield "docker/base/README.md", base_readme()
    for name, image in images.IMAGES.items():
        if "sdk" in image:
            yield image["readme"], sdk_readme(image["sdk"])
    yield "docker/provider-build-environment/README.md", provider_build_environment_readme()


stale = []
for path, content in outputs():
    content = GENERATED_HEADER + re.sub(r"\n{3,}", "\n\n", content).rstrip("\n") + "\n"
    size = len(content.encode("utf-8"))
    if size > MAX_README_BYTES:
        sys.exit(f"error: {path} is {size} bytes, Docker Hub allows at most {MAX_README_BYTES}")
    full_path = os.path.join(ROOT, path)
    existing = open(full_path).read() if os.path.exists(full_path) else None
    if existing == content:
        continue
    if CHECK:
        stale.append(path)
    else:
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, "w") as f:
            f.write(content)
        print(f"wrote {path}")

if stale:
    print("error: these READMEs are out of date:", file=sys.stderr)
    for path in stale:
        print(f"  {path}", file=sys.stderr)
    print("Run `python ./.github/scripts/readme/gen-readmes.py` and commit the result.", file=sys.stderr)
    sys.exit(1)
